// Generated by scripts/generateMarkRules.ts from plugins/alignments/src/shared/basesFilterRules.ts: do not edit, `pnpm autogen` rewrites it.
import { layerEntryProblems } from './basesFilterRuleFacts.ts'

import type { FieldPredicate } from './basesFilterRuleFacts.ts'

export const PROBABILITY = 'probability'
export const CONTEXT = 'context'
export const CODE = 'code'
export const CONTEXTS: readonly string[] = ['CG', 'CHG', 'CHH']
const PATH = 'pileup.bases.filter'

/** The values an `equal` or `oneOf` names, or undefined while none does. */
export function valuesOf(entries: readonly FieldPredicate[]) {
  const named = entries.filter(p => p.oneOf || p.equal !== undefined)
  return named.length > 0
    ? named.flatMap(p => [
        ...(p.oneOf ?? []).map(String),
        ...(p.equal === undefined ? [] : [String(p.equal)]),
      ])
    : undefined
}

/**
 * The `pileup.bases.filter` entries the per-base layer cannot apply, over
 * entries `predicatesOf` already normalized.
 */
export function basesEntryProblems(entries: readonly FieldPredicate[]) {
  const contexts = valuesOf(entries.filter(p => p.field === CONTEXT))
  return [
    ...layerEntryProblems(PATH, entries, {
      [PROBABILITY]: { tests: ['gte', 'gt'], max: 1 },
      [CONTEXT]: { tests: ['oneOf', 'equal'] },
      [CODE]: { tests: ['oneOf', 'equal'] },
    }),
    ...(contexts &&
    !(
      contexts.every(c => CONTEXTS.includes(c)) &&
      (new Set(contexts).size === 1 || new Set(contexts).size === 3)
    )
      ? [
          `${PATH}: context takes one of ${CONTEXTS.join(', ')}, or none to take all three, not ${JSON.stringify(contexts)}`,
        ]
      : []),
  ]
}
